     1→/// Compiler Driver - Platform-Specific Assembly & Linking
     2→///
     3→/// Maps architecture-specific assembly files to assemblers and linkers.
     4→/// Supports: x86-64 (nasm), RISC-V (riscv64-linux-gnu-as), ARM64 (as)
     5→///
     6→/// Usage:
     7→/// var driver = CompilerDriver.init(allocator, .x86_64);
     8→/// try driver.assemble("code.asm", "code.o");
     9→/// try driver.link("code.o", "output");
    10→/// or
    11→/// try driver.compileAndLink("code.asm", "output");
    12→
    13→const std = @import("std");
    14→const Allocator = std.mem.Allocator;
    15→
    16→pub const Target = enum {
    17→    x86_64,
    18→    riscv64,
    19→    arm64,
    20→};
    21→
    22→pub const CompilerDriver = struct {
    23→    allocator: Allocator,
    24→    target: Target,
    25→    verbose: bool,
    26→
    27→    pub fn init(allocator: Allocator, target: Target) CompilerDriver {
    28→        return CompilerDriver{
    29→            .allocator = allocator,
    30→            .target = target,
    31→            .verbose = false,
    32→        };
    33→    }
    34→
    35→    /// Get assembler command name for target
    36→    pub fn getAssembler(self: CompilerDriver) []const u8 {
    37→        return switch (self.target) {
    38→            .x86_64 => "nasm",
    39→            .riscv64 => "riscv64-linux-gnu-as",
    40→            .arm64 => "as",
    41→        };
    42→    }
    43→
    44→    /// Get linker command name
    45→    pub fn getLinker(self: CompilerDriver) []const u8 {
    46→        _ = self;
    47→        return "ld";
    48→    }
    49→
    50→    /// Get assembler flags for target
    51→    pub fn getAssemblerFlags(self: CompilerDriver) []const []const u8 {
    52→        return switch (self.target) {
    53→            .x86_64 => &[_][]const u8{"-f", "elf64"},
    54→            .riscv64 => &[_][]const u8{},
    55→            .arm64 => &[_][]const u8{},
    56→        };
    57→    }
    58→
    59→    /// Get ELF format string for target
    60→    pub fn getElfFormat(self: CompilerDriver) []const u8 {
    61→        return switch (self.target) {
    62→            .x86_64 => "elf64-x86-64",
    63→            .riscv64 => "elf64-littleriscv",
    64→            .arm64 => "elf64-littleaarch64",
    65→        };
    66→    }
    67→
    68→    /// Get linker format flag for target
    69→    pub fn getLinkerFormat(self: CompilerDriver) []const u8 {
    70→        return switch (self.target) {
    71→            .x86_64 => "elf_x86_64",
    72→            .riscv64 => "elf64lriscv",
    73→            .arm64 => "aarch64linux",
    74→        };
    75→    }
    76→
    77→    /// Assemble source file to object file
    78→    /// Example: nasm -f elf64 input.asm -o input.o
    79→    pub fn assemble(self: CompilerDriver, input_file: []const u8, output_file: []const u8) !void {
    80→        const assembler = self.getAssembler();
    81→        const flags = self.getAssemblerFlags();
    82→
    83→        // Build argument list
    84→        var args = std.ArrayList([]const u8).init(self.allocator);
    85→        defer args.deinit();
    86→
    87→        try args.append(assembler);
    88→
    89→        // Add architecture-specific flags
    90→        for (flags) |flag| {
    91→            try args.append(flag);
    92→        }
    93→
    94→        // Input and output
    95→        try args.append(input_file);
    96→        try args.append("-o");
    97→        try args.append(output_file);
    98→
    99→        if (self.verbose) {
   100→            std.debug.print("Assembling: {s}\n", .{input_file});
   101→        }
   102→
   103→        // Spawn assembler
   104→        var child = std.process.Child.init(args.items, self.allocator);
   105→        child.stdin_behavior = .Close;
   106→        child.stdout_behavior = .Inherit;
   107→        child.stderr_behavior = .Inherit;
   108→
   109→        _ = try child.spawnAndWait();
   110→    }
   111→
   112→    /// Link object file to executable
   113→    /// Example: ld -dynamic-linker /lib64/ld-linux-x86-64.so.2 input.o -o output
   114→    pub fn link(self: CompilerDriver, input_file: []const u8, output_file: []const u8) !void {
   115→        const linker = self.getLinker();
   116→        const elf_format = self.getLinkerFormat();
   117→
   118→        // Build argument list
   119→        var args = std.ArrayList([]const u8).init(self.allocator);
   120→        defer args.deinit();
   121→
   122→        try args.append(linker);
   123→        try args.append("-m");
   124→        try args.append(elf_format);
   125→
   126→        // Add dynamic linker for x86-64
   127→        if (self.target == .x86_64) {
   128→            try args.append("-dynamic-linker");
   129→            try args.append("/lib64/ld-linux-x86-64.so.2");
   130→        } else if (self.target == .arm64) {
   131→            try args.append("-dynamic-linker");
   132→            try args.append("/lib/ld-linux-aarch64.so.1");
   133→        }
   134→
   135→        try args.append(input_file);
   136→        try args.append("-o");
   137→        try args.append(output_file);
   138→
   139→        if (self.verbose) {
   140→            std.debug.print("Linking: {s}\n", .{input_file});
   141→        }
   142→
   143→        // Spawn linker
   144→        var child = std.process.Child.init(args.items, self.allocator);
   145→        child.stdin_behavior = .Close;
   146→        child.stdout_behavior = .Inherit;
   147→        child.stderr_behavior = .Inherit;
   148→
   149→        _ = try child.spawnAndWait();
   150→    }
   151→
   152→    /// Compile and link in one step
   153→    pub fn compileAndLink(self: CompilerDriver, asm_file: []const u8, exe_file: []const u8) !void {
   154→        // Generate intermediate object filename
   155→        var obj_buf: [256]u8 = undefined;
   156→        const obj_file = try std.fmt.bufPrint(&obj_buf, "{s}.o", .{exe_file});
   157→
   158→        try self.assemble(asm_file, obj_file);
   159→        try self.link(obj_file, exe_file);
   160→
   161→        // Clean up intermediate object file
   162→        _ = std.fs.cwd().deleteFile(obj_file) catch {};
   163→    }
   164→
   165→    /// Get target architecture as string
   166→    pub fn getTargetString(self: CompilerDriver) []const u8 {
   167→        return switch (self.target) {
   168→            .x86_64 => "x86_64",
   169→            .riscv64 => "riscv64",
   170→            .arm64 => "arm64",
   171→        };
   172→    }
   173→};
