     1→/// Standard Library Generator - Linux Syscall-Based Built-in Functions
     2→///
     3→/// Generates architecture-specific assembly code for standard library functions.
     4→/// Supports: x86-64, RISC-V, ARM64
     5→///
     6→/// Functions:
     7→/// - std_print(ptr, len): write syscall - output bytes to stdout
     8→/// - std_exit(code): exit syscall - terminate program
     9→/// - std_itoa(n, buf): convert integer to ASCII string
    10→///
    11→/// Linux Syscall Numbers:
    12→/// | Function | x86-64 | ARM64 | RISC-V |
    13→/// |----------|--------|-------|--------|
    14→/// | write    | 1      | 64    | 64     |
    15→/// | exit     | 60     | 93    | 93     |
    16→
    17→const std = @import("std");
    18→const Allocator = std.mem.Allocator;
    19→
    20→pub const Backend = enum {
    21→    x86_64,
    22→    riscv64,
    23→    arm64,
    24→};
    25→
    26→pub const StdlibGen = struct {
    27→    allocator: Allocator,
    28→    backend: Backend,
    29→    output: std.ArrayList(u8),
    30→
    31→    pub fn init(allocator: Allocator, backend: Backend) StdlibGen {
    32→        return StdlibGen{
    33→            .allocator = allocator,
    34→            .backend = backend,
    35→            .output = std.ArrayList(u8).init(allocator),
    36→        };
    37→    }
    38→
    39→    pub fn deinit(self: *StdlibGen) void {
    40→        self.output.deinit();
    41→    }
    42→
    43→    /// Emit a line of assembly
    44→    fn emit(self: *StdlibGen, comptime fmt: []const u8, args: anytype) !void {
    45→        try self.output.writer().print(fmt ++ "\n", args);
    46→    }
    47→
    48→    /// Generate all standard library functions
    49→    pub fn generate(self: *StdlibGen) !void {
    50→        try self.emitPrint();
    51→        try self.emit("", .{});
    52→        try self.emitExit();
    53→        try self.emit("", .{});
    54→        try self.emitItoa();
    55→    }
    56→
    57→    /// Generate std_print(ptr, len) - write syscall
    58→    /// Signature: void std_print(void *ptr, int len)
    59→    /// Arguments: ptr in rdi (x86), x0 (ARM64), a0 (RISC-V); len in rsi (x86), x1 (ARM64), a1 (RISC-V)
    60→    pub fn emitPrint(self: *StdlibGen) !void {
    61→        switch (self.backend) {
    62→            .x86_64 => {
    63→                try self.emit(".globl std_print", .{});
    64→                try self.emit("std_print:", .{});
    65→                try self.emit("    push rbp", .{});
    66→                try self.emit("    mov rbp, rsp", .{});
    67→                try self.emit("    mov rax, 1          ; sys_write", .{});
    68→                try self.emit("    mov rdi, 1          ; fd = stdout", .{});
    69→                try self.emit("    ; rsi = ptr (arg0), rdx = len (arg1)", .{});
    70→                try self.emit("    syscall", .{});
    71→                try self.emit("    pop rbp", .{});
    72→                try self.emit("    ret", .{});
    73→            },
    74→            .arm64 => {
    75→                try self.emit(".globl std_print", .{});
    76→                try self.emit("std_print:", .{});
    77→                try self.emit("    stp x29, x30, [sp, #-16]!", .{});
    78→                try self.emit("    mov x29, sp", .{});
    79→                try self.emit("    mov x8, #64         ; sys_write", .{});
    80→                try self.emit("    mov x0, #1          ; fd = stdout", .{});
    81→                try self.emit("    ; x1 = ptr (arg0), x2 = len (arg1)", .{});
    82→                try self.emit("    svc #0              ; syscall", .{});
    83→                try self.emit("    ldp x29, x30, [sp], #16", .{});
    84→                try self.emit("    ret", .{});
    85→            },
    86→            .riscv64 => {
    87→                try self.emit(".globl std_print", .{});
    88→                try self.emit("std_print:", .{});
    89→                try self.emit("    addi sp, sp, -32", .{});
    90→                try self.emit("    sd ra, 24(sp)", .{});
    91→                try self.emit("    sd s0, 16(sp)", .{});
    92→                try self.emit("    li a7, 64           ; sys_write", .{});
    93→                try self.emit("    li a0, 1            ; fd = stdout", .{});
    94→                try self.emit("    ; a1 = ptr (arg0), a2 = len (arg1)", .{});
    95→                try self.emit("    ecall", .{});
    96→                try self.emit("    ld s0, 16(sp)", .{});
    97→                try self.emit("    ld ra, 24(sp)", .{});
    98→                try self.emit("    addi sp, sp, 32", .{});
    99→                try self.emit("    ret", .{});
   100→            },
   101→        }
   102→    }
   103→
   104→    /// Generate std_exit(code) - exit syscall
   105→    /// Signature: void std_exit(int code)
   106→    /// Arguments: code in rdi (x86), x0 (ARM64), a0 (RISC-V)
   107→    pub fn emitExit(self: *StdlibGen) !void {
   108→        switch (self.backend) {
   109→            .x86_64 => {
   110→                try self.emit(".globl std_exit", .{});
   111→                try self.emit("std_exit:", .{});
   112→                try self.emit("    mov rax, 60         ; sys_exit", .{});
   113→                try self.emit("    ; rdi = code (arg0)", .{});
   114→                try self.emit("    syscall", .{});
   115→                try self.emit("    ; unreachable", .{});
   116→            },
   117→            .arm64 => {
   118→                try self.emit(".globl std_exit", .{});
   119→                try self.emit("std_exit:", .{});
   120→                try self.emit("    mov x8, #93         ; sys_exit", .{});
   121→                try self.emit("    ; x0 = code (arg0)", .{});
   122→                try self.emit("    svc #0              ; syscall", .{});
   123→                try self.emit("    ; unreachable", .{});
   124→            },
   125→            .riscv64 => {
   126→                try self.emit(".globl std_exit", .{});
   127→                try self.emit("std_exit:", .{});
   128→                try self.emit("    li a7, 93           ; sys_exit", .{});
   129→                try self.emit("    ; a0 = code (arg0)", .{});
   130→                try self.emit("    ecall", .{});
   131→                try self.emit("    ; unreachable", .{});
   132→            },
   133→        }
   134→    }
   135→
   136→    /// Generate std_itoa(n, buf) - convert integer to ASCII string
   137→    /// Simple implementation: handles 0-9 digits + negative sign
   138→    /// This is a placeholder; full implementation would handle large numbers
   139→    pub fn emitItoa(self: *StdlibGen) !void {
   140→        switch (self.backend) {
   141→            .x86_64 => {
   142→                try self.emit(".globl std_itoa", .{});
   143→                try self.emit("std_itoa:", .{});
   144→                try self.emit("    push rbp", .{});
   145→                try self.emit("    mov rbp, rsp", .{});
   146→                try self.emit("    ; rdi = n (arg0), rsi = buf (arg1)", .{});
   147→                try self.emit("    ; simple version: convert single digit", .{});
   148→                try self.emit("    cmp rdi, 0", .{});
   149→                try self.emit("    jge .L_positive", .{});
   150→                try self.emit("    mov byte [rsi], 45  ; '-'", .{});
   151→                try self.emit("    neg rdi", .{});
   152→                try self.emit("    mov rsi, rsi + 1", .{});
   153→                try self.emit(".L_positive:", .{});
   154→                try self.emit("    add rdi, 48         ; '0'", .{});
   155→                try self.emit("    mov byte [rsi], dil", .{});
   156→                try self.emit("    mov byte [rsi + 1], 0", .{});
   157→                try self.emit("    pop rbp", .{});
   158→                try self.emit("    ret", .{});
   159→            },
   160→            .arm64 => {
   161→                try self.emit(".globl std_itoa", .{});
   162→                try self.emit("std_itoa:", .{});
   163→                try self.emit("    stp x29, x30, [sp, #-16]!", .{});
   164→                try self.emit("    mov x29, sp", .{});
   165→                try self.emit("    ; x0 = n (arg0), x1 = buf (arg1)", .{});
   166→                try self.emit("    cmp x0, 0", .{});
   167→                try self.emit("    b.ge .L_arm_positive", .{});
   168→                try self.emit("    mov w2, 45          ; '-'", .{});
   169→                try self.emit("    strb w2, [x1]", .{});
   170→                try self.emit("    neg x0, x0", .{});
   171→                try self.emit("    add x1, x1, 1", .{});
   172→                try self.emit(".L_arm_positive:", .{});
   173→                try self.emit("    add w0, w0, 48      ; '0'", .{});
   174→                try self.emit("    strb w0, [x1]", .{});
   175→                try self.emit("    mov w2, 0", .{});
   176→                try self.emit("    strb w2, [x1, 1]", .{});
   177→                try self.emit("    ldp x29, x30, [sp], #16", .{});
   178→                try self.emit("    ret", .{});
   179→            },
   180→            .riscv64 => {
   181→                try self.emit(".globl std_itoa", .{});
   182→                try self.emit("std_itoa:", .{});
   183→                try self.emit("    addi sp, sp, -32", .{});
   184→                try self.emit("    sd ra, 24(sp)", .{});
   185→                try self.emit("    sd s0, 16(sp)", .{});
   186→                try self.emit("    ; a0 = n (arg0), a1 = buf (arg1)", .{});
   187→                try self.emit("    bge a0, zero, .L_riscv_positive", .{});
   188→                try self.emit("    li a2, 45           ; '-'", .{});
   189→                try self.emit("    sb a2, 0(a1)", .{});
   190→                try self.emit("    neg a0, a0", .{});
   191→                try self.emit("    addi a1, a1, 1", .{});
   192→                try self.emit(".L_riscv_positive:", .{});
   193→                try self.emit("    addi a0, a0, 48     ; '0'", .{});
   194→                try self.emit("    sb a0, 0(a1)", .{});
   195→                try self.emit("    sb zero, 1(a1)", .{});
   196→                try self.emit("    ld s0, 16(sp)", .{});
   197→                try self.emit("    ld ra, 24(sp)", .{});
   198→                try self.emit("    addi sp, sp, 32", .{});
   199→                try self.emit("    ret", .{});
   200→            },
   201→        }
   202→    }
   203→
   204→    /// Get backend architecture string
   205→    pub fn getBackendString(self: StdlibGen) []const u8 {
   206→        return switch (self.backend) {
   207→            .x86_64 => "x86_64",
   208→            .riscv64 => "riscv64",
   209→            .arm64 => "arm64",
   210→        };
   211→    }
   212→};
