     1→/// LLVM IR Code Generator
     2→///
     3→/// Generates LLVM Intermediate Representation (textual form).
     4→/// - Architecture-independent IR
     5→/// - Virtual registers: %0, %1, %2, ... (SSA form)
     6→/// - Explicit types: i64, i1, void
     7→/// - Use cases: optimization, backend selection, JIT
     8→///
     9→/// Output format:
    10→/// define i64 @function_name(i64 %arg0, i64 %arg1) {
    11→/// entry:
    12→///     %0 = add i64 %arg0, %arg1
    13→///     ret i64 %0
    14→/// }
    15→
    16→const std = @import("std");
    17→const Allocator = std.mem.Allocator;
    18→
    19→pub const LLVMIRCodegen = struct {
    20→    allocator: Allocator,
    21→    output: std.ArrayList(u8),
    22→    vreg_counter: u32,      // Virtual register counter (%0, %1, %2, ...)
    23→    label_counter: u32,     // Label counter (%L0, %L1, %L2, ...)
    24→    current_frame_size: i64,
    25→
    26→    pub fn init(allocator: Allocator) LLVMIRCodegen {
    27→        return LLVMIRCodegen{
    28→            .allocator = allocator,
    29→            .output = std.ArrayList(u8).init(allocator),
    30→            .vreg_counter = 0,
    31→            .label_counter = 0,
    32→            .current_frame_size = 0,
    33→        };
    34→    }
    35→
    36→    pub fn deinit(self: *LLVMIRCodegen) void {
    37→        self.output.deinit();
    38→    }
    39→
    40→    /// Emit a line of LLVM IR
    41→    fn emit(self: *LLVMIRCodegen, comptime fmt: []const u8, args: anytype) !void {
    42→        try self.output.writer().print(fmt ++ "\n", args);
    43→    }
    44→
    45→    /// Allocate a new virtual register
    46→    fn allocVReg(self: *LLVMIRCodegen) u32 {
    47→        const vreg = self.vreg_counter;
    48→        self.vreg_counter += 1;
    49→        return vreg;
    50→    }
    51→
    52→    /// Format virtual register reference
    53→    fn vregRef(vreg: u32, buf: []u8) []const u8 {
    54→        return std.fmt.bufPrint(buf, "%{}", .{vreg}) catch unreachable;
    55→    }
    56→
    57→    /// Generate unique label name
    58→    pub fn newLabel(self: *LLVMIRCodegen, allocator: Allocator) ![]u8 {
    59→        const label = try std.fmt.allocPrint(allocator, "%L{}", .{self.label_counter});
    60→        self.label_counter += 1;
    61→        return label;
    62→    }
    63→
    64→    // ========================================================================
    65→    // Constants and Basic Operations
    66→    // ========================================================================
    67→
    68→    /// emit constant (represented as: %N = add i64 0, C)
    69→    pub fn emitConst(self: *LLVMIRCodegen, value: i64) !u32 {
    70→        const vreg = self.allocVReg();
    71→        try self.emit("    %{} = add i64 0, {}", .{ vreg, value });
    72→        return vreg;
    73→    }
    74→
    75→    /// emit add: %dst = add i64 %lhs, %rhs
    76→    pub fn emitAdd(self: *LLVMIRCodegen, lhs: u32, rhs: u32) !u32 {
    77→        const vreg = self.allocVReg();
    78→        try self.emit("    %{} = add i64 %{}, %{}", .{ vreg, lhs, rhs });
    79→        return vreg;
    80→    }
    81→
    82→    /// emit sub: %dst = sub i64 %lhs, %rhs
    83→    pub fn emitSub(self: *LLVMIRCodegen, lhs: u32, rhs: u32) !u32 {
    84→        const vreg = self.allocVReg();
    85→        try self.emit("    %{} = sub i64 %{}, %{}", .{ vreg, lhs, rhs });
    86→        return vreg;
    87→    }
    88→
    89→    /// emit mul: %dst = mul i64 %lhs, %rhs
    90→    pub fn emitMul(self: *LLVMIRCodegen, lhs: u32, rhs: u32) !u32 {
    91→        const vreg = self.allocVReg();
    92→        try self.emit("    %{} = mul i64 %{}, %{}", .{ vreg, lhs, rhs });
    93→        return vreg;
    94→    }
    95→
    96→    /// emit signed divide: %dst = sdiv i64 %lhs, %rhs
    97→    pub fn emitSdiv(self: *LLVMIRCodegen, lhs: u32, rhs: u32) !u32 {
    98→        const vreg = self.allocVReg();
    99→        try self.emit("    %{} = sdiv i64 %{}, %{}", .{ vreg, lhs, rhs });
   100→        return vreg;
   101→    }
   102→
   103→    /// emit signed remainder: %dst = srem i64 %lhs, %rhs
   104→    pub fn emitSrem(self: *LLVMIRCodegen, lhs: u32, rhs: u32) !u32 {
   105→        const vreg = self.allocVReg();
   106→        try self.emit("    %{} = srem i64 %{}, %{}", .{ vreg, lhs, rhs });
   107→        return vreg;
   108→    }
   109→
   110→    /// emit negate: %dst = sub i64 0, %src
   111→    pub fn emitNeg(self: *LLVMIRCodegen, src: u32) !u32 {
   112→        const vreg = self.allocVReg();
   113→        try self.emit("    %{} = sub i64 0, %{}", .{ vreg, src });
   114→        return vreg;
   115→    }
   116→
   117→    // ========================================================================
   118→    // Comparisons
   119→    // ========================================================================
   120→
   121→    /// emit integer compare: %dst = icmp <cond> i64 %lhs, %rhs
   122→    /// cond: "eq", "ne", "slt", "sle", "sgt", "sge"
   123→    pub fn emitICmp(self: *LLVMIRCodegen, lhs: u32, rhs: u32, cond: []const u8) !u32 {
   124→        const vreg = self.allocVReg();
   125→        try self.emit("    %{} = icmp {s} i64 %{}, %{}", .{ vreg, cond, lhs, rhs });
   126→        return vreg;
   127→    }
   128→
   129→    /// emit zero-extend: %dst = zext i1 %src to i64
   130→    pub fn emitZext(self: *LLVMIRCodegen, src: u32) !u32 {
   131→        const vreg = self.allocVReg();
   132→        try self.emit("    %{} = zext i1 %{} to i64", .{ vreg, src });
   133→        return vreg;
   134→    }
   135→
   136→    // ========================================================================
   137→    // Control Flow
   138→    // ========================================================================
   139→
   140→    /// emit return: ret i64 %value
   141→    pub fn emitRet(self: *LLVMIRCodegen, value: u32) !void {
   142→        try self.emit("    ret i64 %{}", .{value});
   143→    }
   144→
   145→    /// emit return void
   146→    pub fn emitRetVoid(self: *LLVMIRCodegen) !void {
   147→        try self.emit("    ret void", .{});
   148→    }
   149→
   150→    /// emit unconditional branch: br label %label
   151→    pub fn emitBr(self: *LLVMIRCodegen, label: []const u8) !void {
   152→        try self.emit("    br label {s}", .{label});
   153→    }
   154→
   155→    /// emit conditional branch: br i1 %cond, label %true_label, label %false_label
   156→    pub fn emitCondBr(self: *LLVMIRCodegen, cond: u32, true_label: []const u8, false_label: []const u8) !void {
   157→        try self.emit("    br i1 %{}, label {s}, label {s}", .{ cond, true_label, false_label });
   158→    }
   159→
   160→    /// emit label: label_name:
   161→    pub fn emitLabel(self: *LLVMIRCodegen, label: []const u8) !void {
   162→        try self.emit("{s}:", .{label});
   163→    }
   164→
   165→    // ========================================================================
   166→    // Functions
   167→    // ========================================================================
   168→
   169→    /// emit function start: define i64 @name(i64 %arg0, i64 %arg1, ...) {
   170→    pub fn emitFunctionBegin(self: *LLVMIRCodegen, name: []const u8, arg_count: u32) !void {
   171→        var args_str = std.ArrayList(u8).init(self.allocator);
   172→        defer args_str.deinit();
   173→
   174→        for (0..arg_count) |i| {
   175→            if (i > 0) try args_str.appendSlice(", ");
   176→            try std.fmt.format(args_str.writer(), "i64 %arg{}", .{i});
   177→        }
   178→
   179→        try self.emit("define i64 @{s}({s}) {{", .{ name, args_str.items });
   180→        try self.emit("entry:", .{});
   181→    }
   182→
   183→    /// emit function end: }
   184→    pub fn emitFunctionEnd(self: *LLVMIRCodegen) !void {
   185→        try self.emit("}}", .{});
   186→        try self.emit("", .{}); // blank line between functions
   187→    }
   188→
   189→    /// emit function call: %dst = call i64 @name(i64 %arg0, i64 %arg1, ...)
   190→    pub fn emitCall(self: *LLVMIRCodegen, name: []const u8, args: []const u32) !u32 {
   191→        var args_str = std.ArrayList(u8).init(self.allocator);
   192→        defer args_str.deinit();
   193→
   194→        for (args, 0..) |arg, i| {
   195→            if (i > 0) try args_str.appendSlice(", ");
   196→            try std.fmt.format(args_str.writer(), "i64 %{}", .{arg});
   197→        }
   198→
   199→        const vreg = self.allocVReg();
   200→        try self.emit("    %{} = call i64 @{s}({s})", .{ vreg, name, args_str.items });
   201→        return vreg;
   202→    }
   203→
   204→    // ========================================================================
   205→    // Stack and Memory (Alloca, Load, Store) - for future use
   206→    // ========================================================================
   207→
   208→    /// emit alloca: %dst = alloca i64
   209→    pub fn emitAlloca(self: *LLVMIRCodegen) !u32 {
   210→        const vreg = self.allocVReg();
   211→        try self.emit("    %{} = alloca i64", .{vreg});
   212→        return vreg;
   213→    }
   214→
   215→    /// emit load: %dst = load i64, i64* %ptr
   216→    pub fn emitLoad(self: *LLVMIRCodegen, ptr: u32) !u32 {
   217→        const vreg = self.allocVReg();
   218→        try self.emit("    %{} = load i64, i64* %{}", .{ vreg, ptr });
   219→        return vreg;
   220→    }
   221→
   222→    /// emit store: store i64 %value, i64* %ptr
   223→    pub fn emitStore(self: *LLVMIRCodegen, value: u32, ptr: u32) !void {
   224→        try self.emit("    store i64 %{}, i64* %{}", .{ value, ptr });
   225→    }
